actions.script:
def orgId = ec.user.getPreference('ACTIVE_ORGANIZATION')
def destination = ec.entity.find('mantle.facility.Facility').condition('facilityId', incomingTransfer.toFacilityId).one()
def source = ec.entity.find('mantle.facility.Facility').condition('facilityId', incomingTransfer.fromFacilityId).one()
if (destination?.ownerPartyId != orgId || source?.ownerPartyId != orgId) {
    ec.message.addError('Transfer stores must belong to your organization.'); return
}
def items = ec.entity.find('zenith.erp.inventory.StockTransferItem').condition('stockTransferId', stockTransferId).list()
if (!items) ec.message.addError('This transfer has no items to receive.')
for (item in items) {
    def product = ec.entity.find('mantle.product.Product').condition('productId', item.productId).one()
    def qty = item.quantityReceived != null ? item.quantityReceived : item.quantity
    if (product?.ownerPartyId != orgId || qty == null || qty <= 0G || qty > (item.quantity ?: 0G))
        ec.message.addError('Transfer items must be valid products with a positive received quantity no greater than shipped.')
}

if (activeOrgId == '_NA_') activeOrgId = '__NO_ORGANIZATION__'
receiptSearch = [pageNoLimit:'true']
for (key in ['orderId','orderId_op','orderId_ic','entryDate_from','entryDate_thru','vendorPartyId']) {
    def value = ec.web.requestParameters[key]
    if (value instanceof String) receiptSearch[key] = value
}
def sort = ec.web.requestParameters.orderByField?.toString()
if (sort in ['orderId','-orderId','entryDate','-entryDate']) receiptSearch.orderByField = sort == 'orderId' || sort == '-orderId' ? sort : sort + ',orderId'

// Remove fully delivered orders BEFORE pagination; sales do not reopen delivered lines.
def pending = []
receivingViewByOrder = [:]
def checked = new HashSet()
for (po in poList) {
    if (!checked.add(po.orderId)) continue
    def access = ec.service.sync().name('zenith.inventory.ReceiptServices.get#PurchaseOrderAccess').parameters([orderId:po.orderId]).call()
    if (!access.allowed) continue
    def totals = ec.service.sync().name('zenith.inventory.ReceiptServices.get#OrderReceiptQuantities').parameters([orderId:po.orderId]).call().receivedByItem
    def items = ec.entity.find('mantle.order.OrderItem').condition('orderId', po.orderId).list()
    if (items.any { it.productId && (it.quantity ?: 0G) - (it.quantityCancelled ?: 0G) > (totals[it.orderItemSeqId] ?: 0G) }) {
        def productItems = items.findAll { it.productId != null }
        def outstanding = productItems.sum { ((it.quantity ?: 0G) - (it.quantityCancelled ?: 0G) - (totals[it.orderItemSeqId] ?: 0G)).max(0G) } ?: 0G
        def partial = productItems.any { (totals[it.orderItemSeqId] ?: 0G) > 0G }
        def supplier = ec.entity.find('mantle.party.PartyDetail').condition('partyId', po.vendorPartyId).one()
        def state = partial ? 'Partial' : po.statusId.replace('Order', '')
        receivingViewByOrder[po.orderId] = [supplier:supplier?.organizationName ?: [supplier?.firstName,supplier?.lastName].findAll { it }.join(' '), itemCount:productItems.size(), expectedQuantity:outstanding, status:state, statusClass:partial ? 'partial' : po.statusId == 'OrderCompleted' ? 'completed' : 'approved']
        pending.add(po)
    }
}
// Filter only the read model; never modify the stored purchase-order status.
receivingStatus = ec.web.requestParameters.receivingStatus?.toString()
if (!(receivingStatus in ['Approved','Completed','Partial'])) receivingStatus = ''
if (receivingStatus) pending = pending.findAll { receivingViewByOrder[it.orderId].status == receivingStatus }
receivingExportRows = pending.collect { po ->
    def view = receivingViewByOrder[po.orderId]
    [po.orderId, ec.l10n.format(po.entryDate,'dd MMM yyyy'), view.supplier, view.itemCount, view.expectedQuantity, view.status]
}
pending.eachWithIndex { po, index -> receivingViewByOrder[po.orderId].rowNumber = index + 1 }
def positiveInt = { value, fallback ->
    try { return Math.max(0, Integer.parseInt(value?.toString() ?: fallback.toString())) }
    catch (Exception ignored) { return fallback }
}
poListCount = pending.size()
poListPageSize = Math.min(100, Math.max(1, positiveInt(ec.web.requestParameters.pageSize, 10)))
poListPageMaxIndex = Math.max(0, (int)Math.ceil(poListCount / (double)poListPageSize) - 1)
poListPageIndex = Math.min(poListPageMaxIndex, positiveInt(ec.web.requestParameters.pageIndex, 0))
poListPageRangeLow = poListPageIndex * poListPageSize + 1
poListPageRangeHigh = Math.min(poListCount, (poListPageIndex + 1) * poListPageSize)
poList = pending.subList(Math.min(poListCount, poListPageIndex * poListPageSize), poListPageRangeHigh)

            // Escape every request/database value before embedding the presentation-only GET controls.
            receivingOrderNoun = poListCount == 1 ? 'order' : 'orders'
            def html = { value -> (value == null ? '' : value.toString()).replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('"','&quot;').replace("'",'&#39;') }
            def selected = { value, expected -> value == expected ? ' selected' : '' }
            def suppliers = ec.entity.find('mantle.party.PartyDetailAndRole').condition('ownerPartyId', activeOrgId).condition('roleTypeId','Supplier').orderBy('organizationName,partyId').list()
            def supplierOptions = '<option value="">Select supplier</option>' + suppliers.unique { it.partyId }.collect { '<option value="' + html(it.partyId) + '"' + selected(receiptSearch.vendorPartyId,it.partyId) + '>' + html(it.organizationName ?: [it.firstName,it.lastName].findAll { it }.join(' ')) + '</option>' }.join('')
            def statusOptions = '<option value="">Select status</option>' + ['Approved','Completed','Partial'].collect { '<option' + selected(receivingStatus,it) + '>' + it + '</option>' }.join('')
            def fromDate = receiptSearch.entryDate_from?.take(10) ?: ''
            def toDate = receiptSearch.entryDate_thru?.take(10) ?: ''
            def sortValue = ec.web.requestParameters.orderByField?.toString() ?: '-entryDate'
            def sortOptions = ['-entryDate':'Newest first','entryDate':'Oldest first','orderId':'Order number ascending','-orderId':'Order number descending'].collect { key, title -> '<option value="' + key + '"' + selected(sortValue,key) + '>' + title + '</option>' }.join('')
            receivingFilterHtml = """<section class="receiving-filters" aria-labelledby="receiving-filters-title">
<div class="receiving-filter-heading"><h2 id="receiving-filters-title"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M3 4h18l-7 8v8l-4 1v-9z"/></svg> Filters</h2><a class="receiving-secondary" href="FindReceipt">↶ &nbsp;Clear Filters</a></div>
<form id="ReceivingFilters" action="FindReceipt" method="get"><input type="hidden" name="pageSize" value="${poListPageSize}"/>
<div class="receiving-filter-grid">
<label for="receiving-order">Order #<input id="receiving-order" name="orderId" value="${html(receiptSearch.orderId)}" placeholder="Search order #..."/></label>
<label for="receiving-date-from">Date From<input id="receiving-date-from" name="entryDate_from" type="date" value="${html(fromDate)}"/></label>
<label for="receiving-date-to">Date To<input id="receiving-date-to" name="entryDate_thru" type="date" value="${html(toDate)}"/></label>
<label for="receiving-supplier">Supplier<select id="receiving-supplier" name="vendorPartyId">${supplierOptions}</select></label>
<label for="receiving-status">Status<select id="receiving-status" name="receivingStatus">${statusOptions}</select></label></div>
<div class="receiving-filter-bottom"><details><summary>More Filters</summary><div class="receiving-more-grid"><label for="receiving-match">Order number match<select id="receiving-match" name="orderId_op"><option value="contains"${selected(receiptSearch.orderId_op ?: 'contains','contains')}>Contains</option><option value="equals"${selected(receiptSearch.orderId_op,'equals')}>Exact match</option></select></label><label for="receiving-sort">Sort by<select id="receiving-sort" name="orderByField">${sortOptions}</select></label></div></details><div class="receiving-filter-buttons"><button type="reset" class="receiving-secondary">Cancel</button><button type="submit" class="receiving-apply"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/></svg> Apply Filters</button></div></div></form></section>"""
            def parameters = [:] + receiptSearch
            parameters.remove('pageNoLimit'); parameters.orderByField = sortValue
            if (receivingStatus) parameters.receivingStatus = receivingStatus
            def hiddenInputs = parameters.collect { key, value -> '<input type="hidden" name="' + html(key) + '" value="' + html(value) + '"/>' }.join('')
            def pageLink = { index -> 'FindReceipt?' + (parameters + [pageSize:poListPageSize,pageIndex:index]).collect { key,value -> java.net.URLEncoder.encode(key.toString(),'UTF-8') + '=' + java.net.URLEncoder.encode(value.toString(),'UTF-8') }.join('&amp;') }
            def pageSizes = ([10,20,50,100] + poListPageSize).unique().sort().collect { '<option' + selected(poListPageSize,it) + '>' + it + '</option>' }.join('')
            def previous = poListPageIndex > 0 ? '<a class="receiving-page-arrow" aria-label="Previous page" href="' + pageLink(poListPageIndex-1) + '">‹</a>' : '<button class="receiving-page-arrow" aria-label="Previous page" disabled>‹</button>'
            def next = poListPageIndex < poListPageMaxIndex ? '<a class="receiving-page-arrow" aria-label="Next page" href="' + pageLink(poListPageIndex+1) + '">›</a>' : '<button class="receiving-page-arrow" aria-label="Next page" disabled>›</button>'
            receivingPaginationHtml = '<div class="receiving-pagination"><form action="FindReceipt" method="get">' + hiddenInputs + '<label for="receiving-page-size">Rows per page:</label><select id="receiving-page-size" name="pageSize" onchange="this.form.requestSubmit()">' + pageSizes + '</select><noscript><button type="submit">Update</button></noscript></form><span>' + (poListCount ? poListPageRangeLow : 0) + '–' + poListPageRangeHigh + ' of ' + poListCount + '</span>' + previous + next + '</div>'
            def csvCell = { value -> def text = value == null ? '' : value.toString(); if (text ==~ /^[=+@\-].*/) text = "'" + text; '"' + text.replace('"','""') + '"' }
            receivingCsvText = ([['Order #','Order Date','Supplier','Items','Expected Qty','Status']] + receivingExportRows).collect { row -> row.collect(csvCell).join(',') }.join('\r\n')
            receivingExportHref = html(sri.getScreenUrlInstance().cloneUrlInstance().addParameter('renderMode','csv').addParameter('lastStandalone','true').addParameter('saveFilename','receiving-orders.csv').pathWithParams)
